 def para(s,style='BodyText'):
  for a,b in {'architecture118':'architecture 118','of50':'of 50','conditional95%':'conditional 95%','rank7.15':'rank 7.15','among50':'among 50','is50':'is 50','is0.1404':'is 0.1404','are0.7817':'are 0.7817','and3.537':'and 3.537','the426':'the 426','rows501':'rows 501','rows2001':'rows 2001','on501':'on 501','rows2501':'rows 2501','are500':'are 500','original471':'original 471','posterior, 384':'posterior, 384','model118':'model 118','model189':'model 189','Leading 118':'Leading 118','two50-unit':'two 50-unit','and90':'and 90','about39':'about 39','number8251':'number 8251','near44':'near 44','versus0.1812':'versus 0.1812','for384':'for 384','lags1:60':'lags 1:60','lags1:90':'lags 1:90','without59':'without 59','period60':'period 60','rolling30-step':'rolling 30-step','at2500':'at 2500','RMSE0.7105':'RMSE 0.7105','seasonal-naive60':'seasonal-naive 60','only0.358':'only 0.358','near31':'near 31','only87.9%':'only 87.9%','nominal90%':'nominal 90%','explicit60':'explicit 60','or31-period':'or 31-period','across1999':'across 1999','Periodic60':'Periodic 60','at31.25':'at 31.25','length33.43':'length 33.43','depth3':'depth 3','maximum4':'maximum 4','to4.43e-14':'to 4.43e-14','This2x2':'This 2x2','nominal90%':'nominal 90%','is96.8%':'is 96.8%','but83.0%':'but 83.0%','about0.2508':'about 0.2508','is0.2068':'is 0.2068','and0.1768':'and 0.1768','to5.11e-15':'to 5.11e-15','to3.07e-6':'to 3.07e-6','Networks108':'Networks 108','PMLR202':'PMLR 202','revision2ad':'revision 2ad','AutoGP0.1.19':'AutoGP 0.1.19','Julia1.10.10':'Julia 1.10.10'}.items():s=str(s).replace(a,b)
